template<class F>static bool until(F f){const auto end=GetTickCount64()+6000;while(!f()&&GetTickCount64()<end)Sleep(1);return f();}
struct Hold {std::promise<void> release;std::thread writer;std::atomic_bool held=false;bool opened=false;explicit Hold(Manager& manager){auto gate=release.get_future().share();writer=std::thread([this,&manager,gate]{Lock lock(manager.mutex);held=true;gate.wait();});until([&]{return held.load();});}void open(){if(!opened){opened=true;release.set_value();}if(writer.joinable())writer.join();}~Hold(){open();}};
