  for(int n=0;n<2;++n){BatchDownloadEntry entry{"https://files.example.test/file"+std::to_string(n),utf8((root/L"files").wstring()),"file"+std::to_string(n)+".bin","Captured description",{{"User-Agent","Owned browser agent"},{"Authorization","Bearer fixture-secret-value"},{"Referer","https://files.example.test/page"}}};entry.browserSession=session;entry.browserProxy={{"url",entry.address},{"type","direct"}};entry.downloadPage="https://files.example.test/page";draft.entries.push_back(std::move(entry));}
