  auto first=manager.jobs.front();check(str(first->data,"Description")=="Captured description"&&str(first->data,"DownloadPage")==draft.entries[0].downloadPage&&str(first->data,"Status")=="Paused","Owned values preserve the original row draft and Download Later semantics");check(readBrowserSession(first->data)==session&&readBrowserProxy(first->data)==draft.entries[0].browserProxy&&headerValue(readHeaders(first->data),"Authorization")=="Bearer fixture-secret-value","Accepted rows retain their exact protected browser session, route and authenticated request");
  const auto saved=Json::parse(readText(manager.root/L"state.json"));check(saved["Downloads"].size()==2&&!yes(saved["Settings"],"QueuePromptBatch",true),"Queue prompt preference and all admitted rows are durable before acknowledgement");check(readText(manager.root/L"state.json").find("fixture-secret-value")==std::string::npos&&readText(manager.root/L"state.json").find("Owned browser agent")==std::string::npos,"Saved batch context keeps request credentials and browser identity protected");task.release();check(!manager.fileInfoDecisionPending&&!task.valid(),"Acknowledgement joins the accepted worker and releases its guard");
