  task.startAction(manager,[&manager,stale]{return applyBatchAdmission(manager,stale);});check(until([&]{return task.ready();})&&task.get().warning.empty()&&manager.jobs.size()==4,"Retry after persistence failure admits the complete fresh batch once");task.release();
